xpath.attribute:
(('background-image: url(' + question.background_image_url + ');')
 if question and question.background_image_url
 else ('background-image: url(' + page.background_image_url + ');')
 if page and page.background_image_url
 else ('background-image: url(' + survey.background_image_url + ');')
 if survey and survey.background_image_url
 else ('background-image: url(/web/image/survey.survey/%s/background_image);' % survey.id)
 if survey
 else '') + 'background-size: cover; background-position: center center; background-repeat: no-repeat;'

t.script:
(function () {
    var wrappers = document.querySelectorAll('[data-question-type="simple_choice_radio"]');
    wrappers.forEach(function (w) {
        var qTitle = w.closest('.js_question-wrapper') && w.closest('.js_question-wrapper').querySelector('.o_survey_question_title, h1, h2, h3, h4, label');
        var txt = (qTitle && qTitle.textContent || '').toLowerCase();
        if (txt.indexOf('nacionalidad') === -1) {
            return;
        }
        w.querySelectorAll('label.o_survey_choice_btn').forEach(function (lbl) {
            var col = lbl.closest('div');
            if (col) {
                col.style.display = 'none';
            }
        });
    });
})();
